/**
 * One scenario per check of invoice-out-build-standard, for Recharge Desk.
 *
 * Generated by `npx @aipathway/conformance init invoice-out-build-standard`, from
 * https://aipathway.com.au/explore-ai/invoice-out-build-standard, then filled
 * in. The checks are fetched at run time; what is here is the world each check
 * starts in, how the build is driven, and what "held" means.
 *
 * The world is a bookkeeping practice that pays for its clients' software and
 * recharges it monthly. Each job is one client's recharge period for a month
 * in the practice's subscription register, by the id the register issued; its
 * lines are the subscriptions on that client for the month, each with its
 * register line reference (SUB-...) in the description.
 * Recharge price list codes (AUD, ex GST, per month unless noted):
 *   SETUP-SUB      one-off set-up of a new subscription (callout)
 *   ADMIN-HR       practice time administering subscriptions, per hour (labour)
 *   LEDGER-STD     ledger subscription, standard plan (material)
 *   PAYROLL-SEAT   payroll, per employee paid (material)
 *   RECEIPT-SEAT   receipt capture, per user (material)
 *   SEAT-ADD       an extra seat or plan upgrade added mid-month (variation)
 *   STOCK-ADDON    a code the price list does not hold
 *
 * The runner plays the outside world between runs: the practice manager
 * closing a month, the clock moving, and the named person releasing a draft.
 * Every holds() returns a strict boolean.
 */

import { InvoiceOutWorld } from "@aipathway/conformance";

const HOUR = 3_600_000;
const PERSON = "Anh Pham, practice manager";
const BOOK = {
  edition: "recharge-list-2026-10",
  items: [
    { code: "SETUP-SUB", description: "Set up of a new subscription, once", rate: 95 },
    { code: "ADMIN-HR", description: "Subscription administration, per hour", rate: 160 },
    { code: "LEDGER-STD", description: "Ledger subscription, standard plan, per month", rate: 75 },
    { code: "PAYROLL-SEAT", description: "Payroll, per employee paid, per month", rate: 6 },
    { code: "RECEIPT-SEAT", description: "Receipt capture, per user, per month", rate: 14 },
    { code: "SEAT-ADD", description: "Extra seat or plan upgrade, per month", rate: 75 },
  ],
};
const RULE = { name: "Under $250, released by Anh Pham's rule", threshold: 250 };
const done = (id, lines, extra = {}) => ({ id, customerId: `CLIENT-${id}`, status: "complete", completedAt: "2026-10-31T06:00:00.000Z", lines, ...extra });
let subSeq = 400;
const line = (code, qty, kind, extra = {}) => ({ code, qty, kind, description: `register line SUB-${++subSeq}`, ...extra });
const rateOf = (code) => BOOK.items.find((i) => i.code === code)?.rate;

const tick = (build, world) => build(world.ports(), { type: "job.completed" });
const personReleases = (build, world, jobId) => build(world.ports(), { type: "release", jobId, person: PERSON });

const writes = (world) => world.calls.filter((c) => c.port === "write_invoice");
const creates = (world, jobId) => writes(world).filter((c) => c.request?.jobId === jobId && !c.request?.update);
const idx = (world, pred) => world.calls.findIndex(pred);
const sendIdx = (world, invId) => idx(world, (c) => c.port === "issue_notice" && c.request?.send === invId);
const releaseIdx = (world, invId, pred = () => true) => idx(world, (c) => c.port === "gate" && c.request?.release === invId && pred(c.request));
const sentOnes = (world) => new Set(world.sends.map((s) => s.invoiceId));
const describe = (world) =>
  `${world.calls.length} port call(s); invoices ${world.invoices.map((i) => `${i.jobId}:${i.status}${i.parkReason ? `/${i.parkReason}` : ""}`).join(" ") || "none"}; escalations ${world.escalations.map((e) => e.reason).join(" ") || "none"}; sends ${world.sends.length}`;

/** Every send in the world was preceded by a release of that invoice. */
const everySendReleased = (world) =>
  world.calls.every((c, i) => c.port !== "issue_notice" || world.calls.slice(0, i).some((r) => r.port === "gate" && r.request?.release === c.request?.send && (r.request.person || r.request.rule)));

export const scenarios = [
  {
    checkId: "completion-is-the-trigger",
    // 1. Two clients' October closed in the register, a third still open. Two invoices, each written
    // after a read that showed its period closed.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [
          done("RP-2610-031", [line("LEDGER-STD", 1, "material")]),
          done("RP-2610-032", [line("LEDGER-STD", 1, "material"), line("PAYROLL-SEAT", 4, "material")]),
          { id: "RP-2610-033", customerId: "CLIENT-RP-2610-033", status: "open", lines: [line("LEDGER-STD", 1, "material")] },
        ],
      }),
    drive: tick,
    holds: (world) => {
      const ws = writes(world);
      const tracedToCompleteRead = ws.every((c) => {
        const at = world.calls.indexOf(c);
        return world.calls.slice(0, at).some((r) => r.port === "read_job" && r.request?.jobs === true && (r.response?.complete ?? []).includes(c.request?.jobId));
      });
      return (
        world.invoices.length === 2 &&
        world.invoicesFor("RP-2610-031").length === 1 &&
        world.invoicesFor("RP-2610-032").length === 1 &&
        world.invoicesFor("RP-2610-033").length === 0 &&
        ws.length >= 2 &&
        tracedToCompleteRead
      );
    },
    describe,
  },
  {
    checkId: "lines-come-from-the-job",
    // 2. A new subscription set up, the ledger plan and three receipt capture users, each a register line:
    // the invoice carries those three codes and quantities and no others, and names the line each came from.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [
          done("RP-2610-040", [
            line("SETUP-SUB", 1, "callout", { description: "register line SUB-2610-040-A" }),
            line("LEDGER-STD", 1, "material", { description: "register line SUB-2610-040-B" }),
            line("RECEIPT-SEAT", 3, "material", { description: "register line SUB-2610-040-C" }),
          ]),
        ],
      }),
    drive: tick,
    holds: (world) => {
      const inv = world.invoicesFor("RP-2610-040");
      if (inv.length !== 1 || inv[0].status === "parked") return false;
      const got = inv[0].lines.map((l) => `${l.code}x${l.qty}:${l.kind}`).sort().join("|");
      const traced = ["SUB-2610-040-A", "SUB-2610-040-B", "SUB-2610-040-C"].every((ref) => (inv[0].notes ?? "").includes(ref));
      return got === ["SETUP-SUBx1:callout", "LEDGER-STDx1:material", "RECEIPT-SEATx3:material"].sort().join("|") && traced;
    },
    describe,
  },
  {
    checkId: "rates-only-from-the-book",
    // 3. One client carries a stock add-on the practice never put on its recharge list; another is fully priced.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [
          done("RP-2610-050", [line("LEDGER-STD", 1, "material"), line("STOCK-ADDON", 1, "material")]),
          done("RP-2610-051", [line("LEDGER-STD", 1, "material"), line("ADMIN-HR", 0.5, "labour")]),
        ],
      }),
    drive: tick,
    holds: (world) => {
      const bookAt = idx(world, (c) => c.port === "read_pricebook");
      const firstWrite = idx(world, (c) => c.port === "write_invoice");
      const priced = world.invoices.flatMap((i) => i.lines);
      const parked = world.invoicesFor("RP-2610-050");
      const clean = world.invoicesFor("RP-2610-051");
      return (
        bookAt >= 0 &&
        firstWrite > bookAt &&
        priced.length > 0 &&
        priced.every((l) => rateOf(l.code) !== undefined && l.rate === rateOf(l.code)) &&
        parked.length === 1 &&
        parked[0].status === "parked" &&
        parked[0].parkReason === "not_in_pricebook" &&
        !parked[0].lines.some((l) => l.code === "STOCK-ADDON") &&
        clean.length === 1 &&
        clean[0].status !== "parked" &&
        clean[0].lines.length === 2 &&
        !sentOnes(world).has(parked[0].id)
      );
    },
    describe,
  },
  {
    checkId: "variation-needs-a-signature",
    // 4. Two clients had a seat added mid-month: one signed the practice's approval, one asked on the phone.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [
          done("RP-2610-060", [line("LEDGER-STD", 1, "material"), line("SEAT-ADD", 1, "variation", { signedAcceptance: "doc:client-signed-seat-approval-060" })]),
          done("RP-2610-061", [line("LEDGER-STD", 1, "material"), line("SEAT-ADD", 1, "variation")]),
        ],
      }),
    drive: tick,
    holds: (world) => {
      const signed = world.invoicesFor("RP-2610-060");
      const unsigned = world.invoicesFor("RP-2610-061");
      const escalated = world.escalations.some((e) => e.reason === "unsigned_variation" && (e.detail ?? "").includes("RP-2610-061"));
      const noUnsignedBilled = world.invoices.every((i) => i.status === "parked" || !i.lines.some((l) => l.kind === "variation") || i.evidence.length > 0);
      return (
        signed.length === 1 &&
        signed[0].status !== "parked" &&
        signed[0].lines.some((l) => l.kind === "variation" && l.code === "SEAT-ADD") &&
        signed[0].evidence.includes("doc:client-signed-seat-approval-060") &&
        unsigned.length === 1 &&
        unsigned[0].status === "parked" &&
        unsigned[0].parkReason === "unsigned_variation" &&
        !unsigned[0].lines.some((l) => l.kind === "variation") &&
        escalated &&
        noUnsignedBilled &&
        !sentOnes(world).has(unsigned[0].id)
      );
    },
    describe,
  },
  {
    checkId: "stage-invoice-never-claim",
    // 5. A client on a fixed-fee onboarding agreement: the invoice names the stage, and the phrase
    // "progress claim" never appears.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        jobs: [done("RP-2610-070", [line("SETUP-SUB", 3, "callout"), line("ADMIN-HR", 2, "labour")], { contractStage: "Stage 1: software set-up" })],
      }),
    drive: tick,
    holds: (world) => {
      const inv = world.invoicesFor("RP-2610-070");
      const text = JSON.stringify(world.invoices) + JSON.stringify(writes(world).map((c) => c.request)) + JSON.stringify(world.escalations);
      return inv.length === 1 && inv[0].stage === "Stage 1: software set-up" && !/progress\s+claim/i.test(text);
    },
    describe,
  },
  {
    checkId: "one-invoice-per-job",
    // 6. The practice manager closes the same client's month twice, an hour apart.
    world: () => new InvoiceOutWorld({ pricebook: BOOK, jobs: [done("RP-2610-080", [line("LEDGER-STD", 1, "material"), line("PAYROLL-SEAT", 9, "material")])] }),
    drive: async (build, world) => {
      await tick(build, world);
      world.advance(HOUR);
      world.complete("RP-2610-080");
      await tick(build, world);
    },
    holds: (world) => {
      const inv = world.invoicesFor("RP-2610-080");
      const readBeforeEachWrite = writes(world).every((c) => {
        const at = world.calls.indexOf(c);
        return world.calls.slice(0, at).some((r) => r.port === "read_job" && r.request?.invoiceFor === "RP-2610-080");
      });
      const looks = world.calls.filter((c) => c.port === "read_job" && c.request?.invoiceFor === "RP-2610-080").length;
      return inv.length === 1 && Boolean(inv[0].externalId) && creates(world, "RP-2610-080").length === 1 && looks >= 2 && readBeforeEachWrite;
    },
    describe,
  },
  {
    checkId: "written-into-the-ledger",
    // 7. A closed, fully priced month: the write returns Xero's id, stored against the period.
    world: () => new InvoiceOutWorld({ pricebook: BOOK, jobs: [done("RP-2610-090", [line("LEDGER-STD", 1, "material"), line("RECEIPT-SEAT", 2, "material")])] }),
    drive: tick,
    holds: (world) => {
      const c = creates(world, "RP-2610-090");
      const inv = world.invoicesFor("RP-2610-090");
      return c.length === 1 && Boolean(c[0].response?.externalId) && inv.length === 1 && inv[0].externalId === c[0].response.externalId && inv[0].jobId === "RP-2610-090";
    },
    describe,
  },
  {
    checkId: "send-is-a-gate",
    // 8. Three drafts: under the partner's rule threshold, over it, and one in a practice with no rule set.
    // The no-rule practice is a second world carried on the first, so one holds() reads both.
    world: () => {
      const w = new InvoiceOutWorld({
        pricebook: BOOK,
        releaseRule: RULE,
        jobs: [
          done("RP-2610-100", [line("LEDGER-STD", 1, "material"), line("PAYROLL-SEAT", 5, "material")]),
          done("RP-2610-101", [line("LEDGER-STD", 2, "material"), line("PAYROLL-SEAT", 40, "material")]),
        ],
      });
      w.noRule = new InvoiceOutWorld({ pricebook: BOOK, releaseRule: null, jobs: [done("RP-2610-102", [line("LEDGER-STD", 1, "material")])] });
      return w;
    },
    drive: async (build, world) => {
      await tick(build, world);
      await tick(build, world.noRule);
      world.advance(HOUR);
      world.noRule.advance(HOUR);
      // Before the person acts, the over-threshold and no-rule drafts must still be unsent.
      world.unsentBeforePerson = !world.sends.some((s) => s.invoiceId === world.invoicesFor("RP-2610-101")[0]?.id) && world.noRule.sends.length === 0;
      await personReleases(build, world, "RP-2610-101");
      await personReleases(build, world.noRule, "RP-2610-102");
    },
    holds: (world) => {
      const [under] = world.invoicesFor("RP-2610-100");
      const [over] = world.invoicesFor("RP-2610-101");
      const [none] = world.noRule.invoicesFor("RP-2610-102");
      if (!under || !over || !none) return false;
      const underOk =
        under.status === "sent" && under.releasedByRule === RULE.name && !under.releasedBy && releaseIdx(world, under.id, (r) => r.rule === RULE.name) >= 0 && sendIdx(world, under.id) > releaseIdx(world, under.id, (r) => r.rule === RULE.name);
      const routed = idx(world, (c) => c.port === "escalate" && c.request?.reason === "over_threshold" && (c.request?.detail ?? "").includes("RP-2610-101"));
      const overPersonAt = releaseIdx(world, over.id, (r) => r.person === PERSON);
      const overOk =
        over.status === "sent" && over.releasedBy === PERSON && !over.releasedByRule && routed >= 0 && overPersonAt > routed && sendIdx(world, over.id) > overPersonAt && releaseIdx(world, over.id, (r) => Boolean(r.rule)) === -1;
      const nonePersonAt = releaseIdx(world.noRule, none.id, (r) => r.person === PERSON);
      const noneOk = none.status === "sent" && none.releasedBy === PERSON && nonePersonAt >= 0 && sendIdx(world.noRule, none.id) > nonePersonAt && releaseIdx(world.noRule, none.id, (r) => Boolean(r.rule)) === -1;
      return underOk && overOk && noneOk && world.unsentBeforePerson === true && everySendReleased(world) && everySendReleased(world.noRule);
    },
    describe: (world) => `${describe(world)} | no-rule practice: ${world.noRule ? describe(world.noRule) : "absent"}`,
  },
  {
    checkId: "parked-is-a-queue",
    // 9. A failed write, a code not on the list and an unsigned added seat, in a practice whose rule
    // would release everything: every one parked or escalated with a reason, none sent.
    world: () =>
      new InvoiceOutWorld({
        pricebook: BOOK,
        releaseRule: { name: "Release everything under $1m", threshold: 1_000_000 },
        failNextWrite: true,
        jobs: [
          done("RP-2610-110", [line("LEDGER-STD", 1, "material")]),
          done("RP-2610-111", [line("LEDGER-STD", 1, "material"), line("STOCK-ADDON", 1, "material")]),
          done("RP-2610-112", [line("LEDGER-STD", 1, "material"), line("SEAT-ADD", 1, "variation")]),
        ],
      }),
    drive: async (build, world) => {
      await tick(build, world);
      world.advance(HOUR);
      await tick(build, world); // a second run must not send what is parked
    },
    holds: (world) => {
      const parked = world.invoices.filter((i) => i.status === "parked");
      const sent = sentOnes(world);
      const everyNamed = parked.every((p) => p.parkReason && world.escalations.some((e) => e.reason === p.parkReason && (e.detail ?? "").includes(p.jobId)));
      const reasons = new Set(parked.map((p) => p.parkReason));
      const nullWrites = writes(world).filter((c) => !c.request?.update && c.response === null);
      const failedJob = nullWrites[0]?.request?.jobId;
      const failed = world.escalations.filter((e) => e.reason === "write_failed");
      const failedNamed = nullWrites.length === 1 && Boolean(failedJob) && failed.length === 1 && (failed[0].detail ?? "").includes(failedJob);
      const failAt = idx(world, (c) => c.port === "escalate" && c.request?.reason === "write_failed");
      const nullAt = world.calls.indexOf(nullWrites[0]);
      const escalatedAtOnce = failAt > nullAt && !world.calls.slice(nullAt + 1, failAt).some((c) => c.port === "gate" || c.port === "issue_notice");
      const notSent = parked.every((p) => !sent.has(p.id));
      const everyEscalationOwned = world.escalations.every((e) => /Owner: \S/.test(e.detail ?? "") || /Waiting for \S/.test(e.detail ?? ""));
      return parked.length === 2 && reasons.has("not_in_pricebook") && reasons.has("unsigned_variation") && everyNamed && failedNamed && escalatedAtOnce && notSent && everyEscalationOwned && everySendReleased(world);
    },
    describe,
  },
  {
    checkId: "the-record-by-job",
    // 10. One client's month invoiced, released by the practice manager and sent: the record by period id holds it all.
    world: () => new InvoiceOutWorld({ pricebook: BOOK, jobs: [done("RP-2610-120", [line("LEDGER-STD", 1, "material"), line("PAYROLL-SEAT", 12, "material")])] }),
    drive: async (build, world) => {
      await tick(build, world);
      world.advance(2 * HOUR);
      await personReleases(build, world, "RP-2610-120");
    },
    holds: (world) => {
      const { invoice } = world.ports().readRecord("RP-2610-120");
      if (!invoice) return false;
      return (
        Boolean(invoice.externalId) &&
        invoice.jobId === "RP-2610-120" &&
        invoice.lines.length === 2 &&
        invoice.lines.every((l) => l.rate === rateOf(l.code)) &&
        invoice.bookEdition === BOOK.edition &&
        (invoice.releasedBy === PERSON || Boolean(invoice.releasedByRule)) &&
        invoice.status === "sent" &&
        typeof invoice.sentAt === "string"
      );
    },
    describe,
  },
  {
    checkId: "survives-the-builder",
    // 11. Not a runtime property. Never green on a declaration.
    world: () => new InvoiceOutWorld(),
    drive: () => {},
    holds: () => false,
    describe: () =>
      "Declared: the code is public in mesh/nodes/recharge-desk, maintained by AI Pathway (digitalgym). The Xero write and the release rule run on the practice's own Xero and subscription register. Not scored: the practice attaches who else can explain it.",
  },
];

// Check 12 runs only on the practice's own register and Xero, and reports with_us on the stub.
export const liveScenarios = [
  {
    checkId: "pass-test",
    // 12. Real month closes on the practice's own tenant: one period closed twice, one added seat
    // unsigned, one code the list does not hold, one draft over the threshold.
    world: () => new InvoiceOutWorld(),
    drive: async (build, world) => {
      await tick(build, world);
      await tick(build, world);
    },
    holds: (world) => {
      const ws = world.calls.filter((c) => c.port === "write_invoice");
      const byJob = new Map();
      for (const c of ws) if (!c.request?.update && c.request?.jobId) byJob.set(c.request.jobId, (byJob.get(c.request.jobId) ?? 0) + 1);
      const oncePerJob = [...byJob.values()].every((n) => n === 1);
      const parks = new Set(ws.map((c) => c.request?.park).filter(Boolean));
      const overRouted = world.calls.some((c) => c.port === "escalate" && c.request?.reason === "over_threshold");
      return ws.length > 0 && oncePerJob && parks.has("unsigned_variation") && parks.has("not_in_pricebook") && overRouted && everySendReleased(world);
    },
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];
